# ── билдеры блоков ────────────────────────────────────────────────────────────
def text(html):            return ("text", html.strip())
def video(vid):            return ("video", YT + vid)
def image(name):           return ("video", "/static/" + name)
def photo(url):            return ("video", url)
def callout(variant, t):   return ("callout", json.dumps({"variant": variant, "text": t}, ensure_ascii=False))
def checklist(items):      return ("checklist", json.dumps({"items": items}, ensure_ascii=False))
def openq(prompt, crit):   return ("open_answer", json.dumps({"prompt": prompt, "criteria": crit}, ensure_ascii=False))
def quiz(q, opts, ci):     return ("quiz", json.dumps({"question": q, "options": opts, "correctIndex": ci}, ensure_ascii=False))

def tbl(headers, rows):
    """HTML-таблица с инлайн-стилями (рендерится одинаково независимо от prose-CSS)."""
    th = "".join(f'<th style="border:1px solid #cbd5e1;padding:9px 13px;background:#eff6ff;'
                 f'text-align:left;font-weight:700;color:#1e3a8a">{h}</th>' for h in headers)
    body = ""
    for r in rows:
        tds = "".join(f'<td style="border:1px solid #e2e8f0;padding:9px 13px;color:#334155">{c}</td>' for c in r)
        body += f"<tr>{tds}</tr>"
    return (f'<table style="border-collapse:collapse;width:100%;margin:14px 0;font-size:15px">'
            f'<thead><tr>{th}</tr></thead><tbody>{body}</tbody></table>')

def tblock(headers, rows):   return ("text", tbl(headers, rows))   # таблица как отдельный блок

# ── билдеры вопросов теста ────────────────────────────────────────────────────
def qs(i, q, opts, ci):    return {"id": f"q{i}", "type": "single", "question": q, "options": opts, "correctIndex": ci}
def qm(i, q, opts, corr):  return {"id": f"q{i}", "type": "multiple", "question": q, "options": opts, "correctIndex": 0, "correctIndices": corr}
def qb(i, q, is_true):     return {"id": f"q{i}", "type": "boolean", "question": q, "options": ["Верно", "Неверно"], "correctIndex": 0 if is_true else 1}
def qsh(i, q, accepted):   return {"id": f"q{i}", "type": "short", "question": q, "options": [], "correctIndex": 0, "correctText": accepted}
def qo(i, q, ordered):     return {"id": f"q{i}", "type": "ordering", "question": q, "options": ordered, "correctIndex": 0}

def L(title, ltype, *blocks):       return {"title": title, "type": ltype, "blocks": list(blocks)}
def MOD(title, lessons, test):      return {"title": title, "lessons": lessons, "test": test}
def TST(title, ttype, questions, pass_=70, time=0, per=0):
    return {"title": title, "type": ttype, "content": {
        "questions": questions, "pass_threshold": pass_, "shuffle_questions": True,
        "shuffle_options": True, "show_correct_answers": True,
        "questions_per_attempt": per, "time_limit_min": time}}

