# Запись в БД
# ═══════════════════════════════════════════════════════════════════════════════
def wipe(db, cid):
    course = db.query(Course).filter(Course.id == cid).first()
    if not course:
        return
    test_ids = [t.id for m in course.modules for t in m.tests]
    block_ids = [b.id for m in course.modules for l in m.lessons for b in l.blocks]
    if test_ids:
        db.query(ModuleTestAttempt).filter(ModuleTestAttempt.test_id.in_(test_ids)).delete(synchronize_session=False)
    if block_ids:
        db.query(OpenAnswerAttempt).filter(OpenAnswerAttempt.block_id.in_(block_ids)).delete(synchronize_session=False)
        db.query(QuizAttempt).filter(QuizAttempt.block_id.in_(block_ids)).delete(synchronize_session=False)
    db.execute(group_course.delete().where(group_course.c.course_id == cid))
    db.commit()
    db.delete(course)
    db.commit()


def insert(db, data, author_id):
    c = Course(id=data["id"], title=data["title"], description=data["description"],
               is_published=True, cover_image=data["cover"], created_by=author_id,
               sequential=data["sequential"], require_video=data["require_video"])
    db.add(c)
    db.flush()
    for mi, m in enumerate(data["modules"]):
        mid = f'{data["id"]}_m{mi}'
        db.add(Module(id=mid, title=m["title"], order=mi, course_id=c.id))
        for li, les in enumerate(m["lessons"]):
            lid = f'{mid}_l{li}'
            dur = "20 мин" if les["type"] == "video" else "15 мин"
            db.add(Lesson(id=lid, title=les["title"], type=les["type"], duration=dur, order=li, module_id=mid))
            for bi, (btype, content) in enumerate(les["blocks"]):
                db.add(Block(id=f'{lid}_b{bi}', type=btype, content=content, order=bi, lesson_id=lid))
        if m.get("test"):
            t = m["test"]
            db.add(ModuleTest(id=f'{mid}_t', module_id=mid, type=t["type"], title=t["title"],
                              content=json.dumps(t["content"], ensure_ascii=False), order=0))
    if data.get("final"):
        rid = f'{data["id"]}_root'
        db.add(Module(id=rid, title="__root__", order=9999, course_id=c.id))
        t = data["final"]
        db.add(ModuleTest(id=f'{rid}_t', module_id=rid, type="final", title=t["title"],
                          content=json.dumps(t["content"], ensure_ascii=False), order=0))
    db.commit()


def get_or_create_group(db, name, parent_id=None):
    g = db.query(Group).filter(Group.name == name, Group.parent_id == parent_id).first()
    if not g:
        g = Group(name=name, parent_id=parent_id)
        db.add(g); db.commit(); db.refresh(g)
    return g


def main():
    db = SessionLocal()
    admin = db.query(User).filter(User.role == "admin").first()
    author_id = admin.id if admin else None

    for data in (C1, C2):
        wipe(db, data["id"])
        insert(db, data, author_id)
        print(f'✓ Курс создан: {data["title"]}')

    dept = get_or_create_group(db, "Энергетическая служба")
    grp = get_or_create_group(db, "Электрик", parent_id=dept.id)
    for order, cid in enumerate([C1["id"], C2["id"]]):
        exists = db.execute(group_course.select().where(
            (group_course.c.group_id == grp.id) & (group_course.c.course_id == cid))).first()
        if not exists:
            db.execute(group_course.insert().values(group_id=grp.id, course_id=cid, order=order))
    db.commit()
    print(f'✓ Курсы привязаны к должности «Электрик» (id={grp.id}) отдела «Энергетическая служба»')

    # Демо-студент для показа: профессия «Электрик», без прогресса и тестов —
    # чтобы на защите проходить «жирные» курсы и тесты с чистого листа.
    # Курсы группы он получит автоматически при первом входе (enroll_user_in_group_courses).
    demo = db.query(User).filter(User.email == "sidorov@barhleb.by").first()
    if demo:
        demo.group_id = grp.id
        db.commit()
        print(f'✓ Демо-студент {demo.email} → профессия «Электрик», без пройденных тестов')

    for data in (C1, C2):
        c = db.query(Course).filter(Course.id == data["id"]).first()
        mods = [m for m in c.modules if m.title != "__root__"]
        lessons = sum(len(m.lessons) for m in mods)
        blocks = sum(len(l.blocks) for m in mods for l in m.lessons)
        text_chars = sum(len(b.content) for m in mods for l in m.lessons for b in l.blocks if b.type == "text")
        tests = sum(len(m.tests) for m in c.modules)
        print(f'  • {c.title}: {len(mods)} модулей, {lessons} уроков, {blocks} блоков, '
              f'{tests} тестов, ~{text_chars} символов учебного текста')
    db.close()
    print("\nГОТОВО ✅")


if __name__ == "__main__":
    main()
